import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { LemonDialog } from 'lib/lemon-ui/LemonDialog'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import {
    externalDataDestinationsDestroy,
    externalDataDestinationsList,
} from 'products/warehouse_sources/frontend/generated/api'
import { ExternalDataDestinationApi } from 'products/warehouse_sources/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface warehouseDestinationsSceneLogicValues {
    currentTeamId: number | null // teamLogic
    deletingId: string | null
    destinations: ExternalDataDestinationApi[] | null
    destinationsLoading: boolean
    loadError: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface warehouseDestinationsSceneLogicActions {
    confirmDelete: (destination: ExternalDataDestinationApi) => {
        destination: ExternalDataDestinationApi
    }
    deleteDestination: (destination: ExternalDataDestinationApi) => {
        destination: ExternalDataDestinationApi
    }
    loadDestinations: () => any
    loadDestinationsFailure: (error: string, errorObject?: any) => any
    loadDestinationsSuccess: (destinations: ExternalDataDestinationApi[] | null, payload?: any) => any
}

export type warehouseDestinationsSceneLogicType = MakeLogicType<
    warehouseDestinationsSceneLogicValues,
    warehouseDestinationsSceneLogicActions
>

export const warehouseDestinationsSceneLogic = kea<warehouseDestinationsSceneLogicType>([
    path([
        'products',
        'data_warehouse',
        'frontend',
        'scenes',
        'WarehouseDestinationsScene',
        'warehouseDestinationsSceneLogic',
    ]),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    actions({
        deleteDestination: (destination: ExternalDataDestinationApi) => ({ destination }),
        confirmDelete: (destination: ExternalDataDestinationApi) => ({ destination }),
    }),
    loaders(({ values }) => ({
        destinations: [
            // Null, not an empty list: "this project has no destinations" is a verdict about a
            // loaded list, and the scene shows a different screen for it than for "not loaded yet".
            null as ExternalDataDestinationApi[] | null,
            {
                loadDestinations: async () => {
                    const response = await externalDataDestinationsList(String(values.currentTeamId))
                    return response.results ?? []
                },
            },
        ],
    })),
    reducers({
        loadError: [
            null as string | null,
            {
                loadDestinations: () => null,
                loadDestinationsSuccess: () => null,
                loadDestinationsFailure: (_, { error }) => error || 'Could not load destinations',
            },
        ],
        deletingId: [
            null as string | null,
            {
                confirmDelete: (_, { destination }) => destination.id,
                loadDestinationsSuccess: () => null,
                loadDestinationsFailure: () => null,
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        deleteDestination: ({ destination }) => {
            LemonDialog.open({
                title: 'Delete this destination?',
                description: `Deleting ${destination.name} detaches it from every source and table that syncs to it. Those tables keep syncing to their other destinations. Runs already in flight finish where they started.`,
                primaryButton: {
                    children: 'Delete destination',
                    status: 'danger',
                    onClick: () => actions.confirmDelete(destination),
                },
                secondaryButton: { children: 'Cancel' },
            })
        },
        confirmDelete: async ({ destination }) => {
            try {
                await externalDataDestinationsDestroy(String(values.currentTeamId), destination.id)
            } catch (error: any) {
                lemonToast.error(error?.detail || 'Could not delete this destination')
                actions.loadDestinations()
                return
            }
            lemonToast.success(`${destination.name} deleted`)
            actions.loadDestinations()
        },
    })),
    afterMount(({ actions }) => {
        actions.loadDestinations()
    }),
])
